#include <functional>
#include <iostream>
#include <queue>
#include <string>
#include <vector>

struct Op
{
    int id{};
    std::string kind{};
    int finishAt{};
    int bytes{};
};

struct Later
{
    bool operator()(const Op& a, const Op& b) const { return a.finishAt > b.finishAt; }
};

int main()
{
    std::priority_queue<Op, std::vector<Op>, Later> port{};
    port.push({1, "read", 30, 4096});
}
